 import React, { useState, useEffect } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";
import 'bootstrap/dist/css/bootstrap.min.css';
import Form from 'react-bootstrap/Form';
import Button from "react-bootstrap/esm/Button";

const AddTodo = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [date, setDate] = useState("");
  
  useEffect(() => {
    if (!id) return;
    axios.get(`http://localhost:5000/todos`)
      .then(res => {
        const todo = res.data.find(t => t._id === id);
        if (todo) {
          setTitle(todo.title);
          setDescription(todo.description);
          setDate(todo.date);
        } else {
          alert("Event not found");
          navigate("/dashboard");
        }
      });
  }, [id, navigate]);

  const addTodo = () => {
    axios.post("http://localhost:5000/todos", {
      title,
      description,
      date,
      username: localStorage.getItem("username")
    })
    .then(() => navigate("/"));
  };

  const updateTodo = () => {
    axios.put(`http://localhost:5000/todos/${id}`, {
      title,
      description,
        date
    })
    .then(() => navigate("/"));
  };

  return (
    <div className="container mt-5 border-primary border rounded p-4" style={{width: '45rem'}}>
        <h2 className="text-center mt-3">{id ? "Make Changes to Event" : "Add New Event"}</h2>
      <Form className="d-flex flex-column gap-3 px-5 py-3 justify-content-center">
        <Form.Group className="mb-3">
          <Form.Label>Title</Form.Label>
          <Form.Control style={{width: '37rem'}}
            type="text"
            placeholder="Enter event title"
            value={title}
            required
            onChange={(e) => setTitle(e.target.value)}
          />
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Date</Form.Label>
          <Form.Control style={{width: '37rem'}}
            type="date"
            placeholder="Enter event date"
            value={date}
            onChange={(e) => setDate(e.target.value)}
          />
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Description</Form.Label>
          <Form.Control style={{width: '37rem'}}
            type="text"
            placeholder="Enter event description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
        </Form.Group>
      </Form>
      <div className="d-flex justify-content-center">
      <Button variant="primary" className="mt-3" onClick={id ? updateTodo : addTodo}>
        {id ? "Update Event" : "Add Event"}
      </Button>
      </div>
    </div>
  );
};

export default AddTodo;
